class Solution {
public:
    vector<vector<int>> sortTheStudents(vector<vector<int>>& score, int k) {
        int m = score.size();
        vector<int> idx(m);
        iota(idx.begin(), idx.end(), 0);
        sort(idx.begin(), idx.end(), [&](int a, int b){ return score[a][k] > score[b][k]; });
        vector<vector<int>> res;
        for (int i : idx) res.push_back(score[i]);
        return res;
    }
};

c.java:
class Solution {
    public int[][] sortTheStudents(int[][] score, int k) {
        int m = score.length;
        Integer[] idx = new Integer[m];
        for (int i = 0; i < m; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> Integer.compare(score[b][k], score[a][k]));
        int[][] res = new int[m][];
        for (int i = 0; i < m; i++) res[i] = score[idx[i]];
        return res;
    }
}

